import { createHash } from "node:crypto";

const SAMPLE_VERSION = 1;
const MAX_REPRODUCER_LENGTH = 16_384;
const MAX_TRACE_LENGTH = 1_048_576;
const RECENT_DAYS = 7;
const REPRODUCER_KINDS = new Set(["scenario", "route", "command-id"]);
const SECRET_PATTERNS = [
  /-----BEGIN (?:RSA |EC |OPENSSH |DSA )?PRIVATE KEY-----/i,
  /\bsk-[A-Za-z0-9_-]{8,}\b/,
  /\bphc_[A-Za-z0-9_-]{8,}\b/,
  /\bghp_[A-Za-z0-9]{20,}\b/,
  /\bAKIA[A-Z0-9]{12,}\b/,
];
const FORBIDDEN_KEYS = /(?:^|[._-])(raw[._-]?prompt|prompt|messages|body|authorization|api[_-]?key|headers)(?:$|[._-])/i;
const FAILURE_OUTCOMES = new Set(["fail", "failed", "failure", "error", "errored"]);
const NON_FAILURE_OUTCOMES = new Set(["pass", "passed", "success", "succeeded", "rejected", "reject", "cancelled", "canceled", "cancel"]);

function assertObject(value, name) {
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    throw new TypeError(`${name} must be an object`);
  }
  return value;
}

function assertNonEmptyString(value, name) {
  if (typeof value !== "string" || value.trim() === "") {
    throw new TypeError(`${name} must be a non-empty string`);
  }
  return value;
}

function jsonText(value) {
  return JSON.stringify(value, (_key, item) => item);
}

function walk(value, visit, key = "") {
  visit(key, value);
  if (Array.isArray(value)) {
    for (const item of value) walk(item, visit, key);
    return;
  }
  if (value && typeof value === "object") {
    for (const [childKey, childValue] of Object.entries(value)) {
      walk(childValue, visit, childKey);
    }
  }
}

/**
 * Returns sensitive-field names or secret-like values found in a trace.
 * The check is intentionally conservative: a match rejects the entire trace.
 */
export function findSensitiveTraceData(trace) {
  assertObject(trace, "trace");
  const findings = [];
  const seen = new Set();
  walk(trace, (key, value) => {
    if (key && FORBIDDEN_KEYS.test(key)) {
      const finding = `forbidden-field:${key}`;
      if (!seen.has(finding)) {
        seen.add(finding);
        findings.push(finding);
      }
    }
    if (typeof value === "string") {
      for (const pattern of SECRET_PATTERNS) {
        if (pattern.test(value)) {
          const finding = `secret-pattern:${pattern.source}`;
          if (!seen.has(finding)) {
            seen.add(finding);
            findings.push(finding);
          }
        }
      }
      if (/\braw prompt\b/i.test(value)) {
        const finding = "forbidden-value:raw prompt";
        if (!seen.has(finding)) {
          seen.add(finding);
          findings.push(finding);
        }
      }
    }
  });
  return findings;
}

export function isTraceSafeForConversion(trace) {
  return findSensitiveTraceData(trace).length === 0;
}

function normalizeOutcome(trace) {
  const outcome = trace.outcome ?? trace.status ?? trace.result ?? trace.verdict;
  const normalized = typeof outcome === "string" ? outcome.trim().toLowerCase() : "";
  if (FAILURE_OUTCOMES.has(normalized)) return "failure";
  if (NON_FAILURE_OUTCOMES.has(normalized)) return normalized;
  if (trace.failed === true || trace.beforeFix === "fail" || trace.before_fix === "fail") return "failure";
  return "pass";
}

function normalizeReproducer(trace) {
  const source = trace.reproducer;
  if (!source || typeof source !== "object" || Array.isArray(source)) {
    throw new TypeError("trace.reproducer must be an object");
  }
  const kind = assertNonEmptyString(source.kind, "reproducer.kind").toLowerCase();
  if (!REPRODUCER_KINDS.has(kind)) {
    throw new TypeError(`reproducer.kind must be one of: ${[...REPRODUCER_KINDS].join(", ")}`);
  }
  const definition = source.definition ?? source.value ?? source.reference ?? source.target;
  if (definition === undefined || definition === null) {
    throw new TypeError("reproducer.definition is required");
  }
  if (typeof definition !== "string" && typeof definition !== "number" && typeof definition !== "boolean") {
    throw new TypeError("reproducer.definition must be a string, number, or boolean");
  }
  const serialized = jsonText(definition);
  if (Buffer.byteLength(serialized, "utf8") > MAX_REPRODUCER_LENGTH) {
    throw new RangeError(`reproducer exceeds ${MAX_REPRODUCER_LENGTH} bytes`);
  }
  if (kind === "command-id" && !/^[A-Za-z0-9][A-Za-z0-9._:-]{0,255}$/.test(String(definition))) {
    throw new TypeError("command-id reproducer must be a bounded identifier, not a shell command");
  }
  return { kind, definition };
}

function normalizeSelector(trace) {
  const source = trace.selector ?? trace;
  const runId = source.runId ?? source.run_id;
  const attempt = source.attempt ?? source.attemptNumber ?? source.attempt_number;
  assertNonEmptyString(runId, "selector.runId");
  if (!Number.isInteger(attempt) || attempt < 0) {
    throw new TypeError("selector.attempt must be a non-negative integer");
  }
  return { runId, attempt };
}

function canonicalize(value) {
  if (Array.isArray(value)) return value.map(canonicalize);
  if (value && typeof value === "object") {
    return Object.fromEntries(Object.keys(value).sort().map((key) => [key, canonicalize(value[key])]));
  }
  return value;
}

function digestSample(sample) {
  const { digest, ...unsigned } = sample;
  return createHash("sha256").update(JSON.stringify(canonicalize(unsigned)), "utf8").digest("hex");
}

/**
 * Explicitly converts one selected, already-redacted trace into one replayable sample.
 * No file or process side effects are performed.
 */
export function convertTraceToEvalSample(trace) {
  assertObject(trace, "trace");
  const serializedTrace = JSON.stringify(trace);
  if (Buffer.byteLength(serializedTrace, "utf8") > MAX_TRACE_LENGTH) {
    throw new RangeError(`trace exceeds ${MAX_TRACE_LENGTH} bytes`);
  }
  const sensitiveFindings = findSensitiveTraceData(trace);
  if (sensitiveFindings.length > 0) {
    const error = new Error(`trace rejected because sensitive data was detected: ${sensitiveFindings.join(", ")}`);
    error.code = "TRACE_NOT_REDACTED";
    error.findings = sensitiveFindings;
    throw error;
  }
  const selector = normalizeSelector(trace);
  const reproducer = normalizeReproducer(trace);
  const outcome = normalizeOutcome(trace);
  const beforeFix = outcome === "failure" ? "fail" : "pass";
  const sample = {
    version: SAMPLE_VERSION,
    selector,
    reproducer,
    expected: {
      beforeFix,
      afterFix: "pass",
    },
  };
  sample.digest = `sha256:${digestSample(sample)}`;
  return sample;
}

function isWithinRecentWindow(trace, now) {
  const timestamp = trace.timestamp ?? trace.createdAt ?? trace.created_at;
  if (timestamp === undefined) return true;
  const parsed = typeof timestamp === "number" ? timestamp : Date.parse(String(timestamp));
  if (!Number.isFinite(parsed)) {
    throw new TypeError("trace timestamp must be a valid date");
  }
  const age = now.getTime() - parsed;
  return age <= RECENT_DAYS * 24 * 60 * 60 * 1000 && age >= -60 * 60 * 1000;
}

/**
 * Converts only the explicitly selected traces. Every rejected trace produces its
 * own diagnostic and is never included in samples.
 */
export function convertSelectedTracesToEvalSamples(traces, options = {}) {
  if (!Array.isArray(traces)) throw new TypeError("traces must be an array");
  const now = options.now instanceof Date ? options.now : new Date();
  if (Number.isNaN(now.getTime())) throw new TypeError("options.now must be a valid Date");
  const selectedRunIds = options.selectedRunIds === undefined
    ? undefined
    : new Set(options.selectedRunIds.map((runId) => assertNonEmptyString(runId, "selectedRunIds entry")));
  const samples = [];
  const diagnostics = [];
  for (let index = 0; index < traces.length; index += 1) {
    const trace = traces[index];
    try {
      assertObject(trace, `traces[${index}]`);
      const selector = normalizeSelector(trace);
      if (selectedRunIds && !selectedRunIds.has(selector.runId)) continue;
      if (!isWithinRecentWindow(trace, now)) continue;
      samples.push(convertTraceToEvalSample(trace));
    } catch (error) {
      diagnostics.push({
        index,
        runId: trace && typeof trace === "object" ? trace.runId ?? trace.run_id ?? null : null,
        attempt: trace && typeof trace === "object" ? trace.attempt ?? trace.attemptNumber ?? null : null,
        code: error && error.code ? error.code : "TRACE_CONVERSION_REJECTED",
        reason: error instanceof Error ? error.message : String(error),
      });
    }
  }
  return { samples, diagnostics };
}

export const convertTracesToEvalSamples = convertSelectedTracesToEvalSamples;
export const traceToEvalSample = convertTraceToEvalSample;

export interface TraceReproducer {
  kind: "scenario" | "route" | "command-id";
  definition: string | number | boolean;
}

export interface TraceSelector {
  runId: string;
  attempt: number;
}

export interface EvalSample {
  version: 1;
  selector: TraceSelector;
  reproducer: TraceReproducer;
  expected: {
    beforeFix: "fail" | "pass";
    afterFix: "pass";
  };
  digest: string;
}

export interface TraceInput {
  runId?: string;
  run_id?: string;
  attempt?: number;
  attemptNumber?: number;
  attempt_number?: number;
  outcome?: string;
  status?: string;
  result?: string;
  verdict?: string;
  failed?: boolean;
  beforeFix?: "fail" | "pass";
  before_fix?: "fail" | "pass";
  timestamp?: string | number;
  createdAt?: string | number;
  created_at?: string | number;
  reproducer: TraceReproducer;
  selector?: TraceSelector;
  [key: string]: unknown;
}

export interface TraceDiagnostic {
  index: number;
  runId: string | null;
  attempt: number | null;
  code: string;
  reason: string;
}

export interface TraceConversionBatch {
  samples: EvalSample[];
  diagnostics: TraceDiagnostic[];
}

export function findSensitiveTraceData(trace: Record<string, unknown>): string[];
export function isTraceSafeForConversion(trace: Record<string, unknown>): boolean;
export function convertTraceToEvalSample(trace: TraceInput): EvalSample;
export function convertSelectedTracesToEvalSamples(
  traces: TraceInput[],
  options?: { selectedRunIds?: string[]; now?: Date },
): TraceConversionBatch;
export function convertTracesToEvalSamples(
  traces: TraceInput[],
  options?: { selectedRunIds?: string[]; now?: Date },
): TraceConversionBatch;
export function traceToEvalSample(trace: TraceInput): EvalSample;

# G03 closure: trace-to-eval-sample

## 设计

`scripts/lib/trace-to-eval-sample.mjs` 是纯转换库。它不读取时钟以外的外部状态，不写文件、不执行命令，也不启动 automation 或后台进程。批处理必须收到调用方提供的轨迹集合；需要按 run 限定时，调用方传入 `selectedRunIds`。

## 使用

```js
import {
  convertSelectedTracesToEvalSamples,
} from "../../scripts/lib/trace-to-eval-sample.mjs";

const result = convertSelectedTracesToEvalSamples(selectedTraces, {
  selectedRunIds: ["run-123"],
});

await writeSamples(result.samples);
await writeDiagnostics(result.diagnostics);
```

调用方负责持久化，且不得覆盖或删除原始轨迹。每个结果样例包含 `selector.runId`、`selector.attempt`、有界 reproducer、before-fix/after-fix 期望值以及 `sha256:` digest。

## 安全边界

转换器在构造样例之前扫描完整输入。敏感字段名和常见密钥模式均采用 fail-closed 策略：一旦命中，整条轨迹被拒绝。诊断仅记录索引、runId、attempt、错误码和原因，不复制秘密值。未脱敏轨迹不会产生部分样例。

`command-id` reproducer 仅接受不超过 256 字符的字母、数字、点、下划线、冒号和连字符标识符，不支持 shell 字符串。

## 验证建议

使用固定轨迹分别验证失败、成功、拒绝、取消、敏感字段、秘密值、错误 runId、过期轨迹、无效 command-id、空 attempt、确定性 digest，以及批处理中每条拒绝轨迹的独立诊断。确认测试过程未创建后台任务或修改产品配置。

